UPDATE public.mrfluent_english_lessons le
SET video_url = v.video_url,
    updated_at = now()
FROM public.mrfluent_english_units u,
     public.mrfluent_english_levels l,
     video_resources v
WHERE le.unit_id = u.id
  AND u.level_id = l.id
  AND l.code = v.level_code
  AND u.unit_number = v.unit_number
  AND le.sort_order = v.lesson_order
RETURNING l.code AS level_code, u.unit_number, le.sort_order, le.title, le.video_url;
